#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 5);

void setup() {
  pinMode(2, INPUT_PULLUP);
  display.setBrightness(7);
  display.showNumberDec(digitalRead(2) == LOW ? 1111 : 0, true, 4, 0);
}

void loop() {
  display.showNumberDec(digitalRead(2) == LOW ? 1111 : 0, true, 4, 0);
  delay(10);
}
